from pathlib import Path
import subprocess, json, os, struct
ROOT=Path(__file__).resolve().parents[1]
rec=ROOT/'test_evidence'/'recordings'; meta=ROOT/'test_evidence'/'metadata'; deleted=ROOT/'test_evidence'/'deleted'; rec.mkdir(parents=True,exist_ok=True);meta.mkdir(parents=True,exist_ok=True);deleted.mkdir(parents=True,exist_ok=True)
# Three short real MP4s generated by FFmpeg test source. These are genuine decodable video fixtures.
for i,color in enumerate(['red','blue','green'],1):
    out=rec/f'camera0{i}.mp4'
    subprocess.run(['ffmpeg','-y','-f','lavfi','-i',f'color=c={color}:s=640x360:r=15','-t','5','-pix_fmt','yuv420p','-c:v','libx264','-movflags','+faststart',str(out)],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
(meta/'dvr_metadata.json').write_text(json.dumps({'vendor':'Demo DVR Profile','model':'FV-DVR-16CH','channels':16,'timezone':'Asia/Kolkata','clock_offset_seconds':140},indent=2))
# Controlled recovery fixture: a non-video binary container with an unmistakable known fixture signature and payload.
source=deleted/'controlled_recovery_fixture.bin';prefix=b'UNALLOCATED-REGION\x00'*8192;payload=b'FVRECOVER:H264\n'+b'KNOWN-CONTROLLED-VIDEO-FRAGMENT\x00'*5000+b'\n--END-FRAGMENT--\n';suffix=b'UNALLOCATED-REGION-END\x00'*4096;source.write_bytes(prefix+payload+suffix)
# Evidence container with demo marker and a valid MP4 payload is useful for identification tests.
container=ROOT/'test_evidence'/'demo_dvr_evidence.bin';mp4=(rec/'camera01.mp4').read_bytes();container.write_bytes(b'FIREVISION_DEMO_DVR\n'+meta.joinpath('dvr_metadata.json').read_bytes()+b'\n'+mp4)
print('Generated:',container,source)
